"""Generate replay fixtures for LLM extraction tests from recorded LLM runs (or live LLM).

Per `tz_ml_extract_fix_v2.md` §3.8 (`Ф6`), replay fixtures MUST NOT be generated by
copying `eval/gold/*/gold.json`. Instead, this script converts raw LLM responses from
`eval/runs/<run_dir>/` (or invokes the live LLM against `brief.md` when `--live` is set)
into compact-schema replay fixtures in `ml/tests/fixtures/llm/brief_XXX_response.json`.

Usage:
    # From recorded LLM run directory
    python -m tests.fixtures.llm.generate_replay_fixtures --runs-dir ../eval/runs/recorded_llm_v3

    # Live capture from configured LLM endpoint
    python -m tests.fixtures.llm.generate_replay_fixtures --live
"""

from __future__ import annotations

import argparse
import asyncio
import json
import sys
from pathlib import Path
from typing import Any

FIXTURES_DIR = Path(__file__).resolve().parent
REPO_ROOT = FIXTURES_DIR.parents[3]
ML_DIR = REPO_ROOT / "ml"
GOLD_DIR = REPO_ROOT / "eval" / "gold"
DEFAULT_RUNS_DIR = REPO_ROOT / "eval" / "runs" / "recorded_llm_v3"

if str(ML_DIR) not in sys.path:
    sys.path.insert(0, str(ML_DIR))


async def _capture_live_brief(brief_path: Path) -> dict[str, Any]:
    """Call live LLM on a single brief.md (never reads gold.json)."""
    from app.extract.prompt import build_extract_prompt
    from app.extract.taxonomy import get_registry
    from app.llm.client import LLMClient
    from app.llm.config import get_settings

    settings = get_settings()
    registry = get_registry()
    client = LLMClient(settings)
    text = brief_path.read_text(encoding="utf-8")
    messages = build_extract_prompt(text, registry, "ru")
    resp = await client.chat(messages, temperature=0, seed=42, max_tokens=2048)
    return {
        "content": resp.content,
        "tokens_in": resp.tokens_in,
        "tokens_out": resp.tokens_out,
        "model": resp.model,
    }


def _convert_run_file_to_fixture(run_file: Path) -> dict[str, Any]:
    """Convert a recorded run JSON file in `eval/runs/` to a replay fixture dict."""
    raw = json.loads(run_file.read_text(encoding="utf-8"))
    if "content" in raw and isinstance(raw["content"], str):
        return {
            "content": raw["content"],
            "tokens_in": int(raw.get("tokens_in", 1800)),
            "tokens_out": int(raw.get("tokens_out", 320)),
            "model": str(raw.get("model", "qwen/qwen-2.5-72b-instruct")),
        }

    items = raw.get("raw_response") or raw.get("llm_raw") or raw.get("items") or []
    compact_items: list[dict[str, Any]] = []
    for item in items:
        if "role_id" in item and "quote" in item:
            compact_items.append(item)
        else:
            role = item.get("role") or {}
            comp = item.get("competency") or {}
            ev_list = item.get("evidence") or [{}]
            compact_items.append(
                {
                    "role_id": role.get("role_id", ""),
                    "competency_id": comp.get("competency_id") if isinstance(comp, dict) else None,
                    "quote": ev_list[0].get("quote", "") if ev_list else "",
                    "level": item.get("level", 3),
                    "criticality": item.get("criticality", "must"),
                    "headcount": item.get("headcount", 1),
                    "confidence": item.get("confidence", 0.9),
                    "needs_review": item.get("needs_review", False),
                }
            )
    stats = raw.get("llm_stats") or raw.get("stats") or {}
    content = json.dumps(compact_items, ensure_ascii=False, indent=2)
    return {
        "content": content,
        "tokens_in": int(stats.get("tokens_in") or 1850),
        "tokens_out": int(stats.get("tokens_out") or max(120, len(content) // 3)),
        "model": str(raw.get("model", "qwen/qwen-2.5-72b-instruct")),
    }


async def _main_async() -> None:
    parser = argparse.ArgumentParser(
        description="Build LLM replay fixtures from recorded eval/runs or live LLM (never from gold.json)"
    )
    parser.add_argument(
        "--runs-dir",
        type=Path,
        default=DEFAULT_RUNS_DIR,
        help="Path to recorded LLM run directory in eval/runs/",
    )
    parser.add_argument(
        "--live",
        action="store_true",
        help="Query live LLM endpoint on brief.md instead of reading eval/runs/",
    )
    args = parser.parse_args()

    brief_dirs = sorted(GOLD_DIR.glob("brief_*"))
    count = 0

    for brief_dir in brief_dirs:
        num = brief_dir.name.split("_")[1]
        out_path = FIXTURES_DIR / f"brief_{num}_response.json"

        if args.live:
            fixture = await _capture_live_brief(brief_dir / "brief.md")
        else:
            candidates = [
                args.runs_dir / f"{brief_dir.name}_llm.json",
                args.runs_dir / f"{brief_dir.name}_stages.json",
                args.runs_dir / f"brief_{num}_response.json",
            ]
            run_file = next((p for p in candidates if p.exists()), None)
            if run_file is None:
                print(f"  SKIP {brief_dir.name}: no recorded run in {args.runs_dir}")
                continue
            fixture = _convert_run_file_to_fixture(run_file)

        out_path.write_text(
            json.dumps(fixture, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        count += 1
        print(f"  OK {brief_dir.name} -> {out_path.name}")

    print(f"\nGenerated {count} replay fixtures in {FIXTURES_DIR}")


def main() -> None:
    asyncio.run(_main_async())


if __name__ == "__main__":
    main()
